
#include <stdio.h>
#include <string.h>

int main() {
    char code[20][100];
        int n, i, live[20] = {0};

            printf("Enter number of statements: ");
                scanf("%d", &n);
                    getchar();

                        printf("Enter statements:\n");
                            for (i = 0; i < n; i++)
                                    fgets(code[i], 100, stdin);

                                        // Mark statements that produce output
                                            for (i = 0; i < n; i++)
                                                    if (strstr(code[i], "printf") ||
                                                                strstr(code[i], "return"))
                                                                            live[i] = 1;

                                                                                // Trace dependencies backwards
                                                                                    for (i = n - 1; i >= 0; i--) {
                                                                                            if (live[i]) {
                                                                                                        char *eq = strchr(code[i], '=');
                                                                                                                    if (eq) {
                                                                                                                                    char *p = eq + 1;
                                                                                                                                                    for (int j = 0; j < i; j++) {
                                                                                                                                                                        char var[50];
                                                                                                                                                                                            int k = 0;

                                                                                                                                                                                                                while (code[j][k] == ' ') k++;
                                                                                                                                                                                                                                    while ((code[j][k] >= 'a' &&
                                                                                                                                                                                                                                                                code[j][k] <= 'z') ||
                                                                                                                                                                                                                                                                                           (code[j][k] >= 'A' &&
                                                                                                                                                                                                                                                                                                                       code[j][k] <= 'Z'))
                                                                                                                                                                                                                                                                                                                                               k++;

                                                                                                                                                                                                                                                                                                                                                                   int len = k;
                                                                                                                                                                                                                                                                                                                                                                                       while (code[j][k] == ' ') k++;

                                                                                                                                                                                                                                                                                                                                                                                                           if (code[j][k] == '=') {
                                                                                                                                                                                                                                                                                                                                                                                                                                   char name[50];
                                                                                                                                                                                                                                                                                                                                                                                                                                                           strncpy(name, code[j], len);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   name[len] = '\0';

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           if (strstr(p, name))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       live[j] = 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       printf("\nOptimized Code:\n");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           for (i = 0; i < n; i++)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   if (live[i])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               printf("%s", code[i]);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   return 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   